WITH metrics AS (SELECT id, order_id, product_id, unit_price, LEAD(quantity, 1) OVER w_recent AS next_quantity, NTILE(3) OVER (PARTITION BY order_id ORDER BY quantity DESC, id) AS quantity_bucket, LAG(quantity, 1) OVER (ORDER BY quantity, id) AS prev_quantity FROM order_items WHERE product_id IS NOT NULL WINDOW w_recent AS (PARTITION BY order_id, product_id ORDER BY quantity, id)) SELECT product_id, CASE WHEN quantity_bucket >= 9 THEN 'HIGH' ELSE 'LOW' END AS quantity_bucket_tier, PERCENTILE_APPROX(next_quantity, ARRAY(0.25, 0.5, 0.75)) AS next_quantity_quartiles, STDDEV_SAMP(unit_price) AS unit_price_stddev, APPROX_PERCENTILE(prev_quantity, ARRAY(0.25, 0.5, 0.75)) AS prev_quantity_quartiles FROM metrics GROUP BY product_id, quantity_bucket_tier ORDER BY product_id;
